use neko_wire::{decode_frames, encode_frames, decode_varint, encode_varint, Frame};
fn bytes(seed: u64, len: usize) -> Vec<u8> { let mut x=seed; (0..len).map(|_| { x=x.wrapping_mul(6364136223846793005).wrapping_add(1); (x>>32) as u8 }).collect() }
#[test] fn deterministic_frame_round_trip_property() { for seed in 0..256u64 { let frames=(0..(1+seed as usize%8)).map(|i| match i%4 { 0=>Frame::Data(bytes(seed^i as u64,(seed as usize+i)%33)), 1=>Frame::Datagram(bytes(seed.wrapping_add(i as u64),(seed as usize*3+i)%65)), 2=>Frame::DeliveryAck(bytes(seed,i%17)), _=>Frame::UnknownIgnorable{frame_type:0x11,payload:bytes(seed,i%9)} }).collect::<Vec<_>>(); let encoded=encode_frames(&frames).expect("bounded"); assert_eq!(decode_frames(&encoded).unwrap(),frames,"seed={seed}"); } }
#[test] fn deterministic_varint_round_trip_property_and_canonical_rejection() { let values=[0,1,127,128,255,16384,u32::MAX as u64,u64::MAX-1,u64::MAX]; for value in values { let mut out=Vec::new(); encode_varint(value,&mut out); assert_eq!(decode_varint(&out),Ok((value,out.len()))); } assert!(decode_varint(&[0x80,0]).is_err()); }
